export function DeepLink({
  path = "{{path}}",
  scheme = "{{scheme}}",
  accent = "{{accent}}",
  showQuery = {{showQuery}},
}) {
  return (
    <a href="#" style={{ display: "inline-flex", alignItems: "center", gap: 8, fontFamily: "SFMono-Regular, Consolas, monospace", fontSize: 13, color: "#241430", textDecoration: "none", padding: "10px 14px", background: "#FAF7F2", borderRadius: 999, border: "1px solid rgba(36,20,48,.12)" }}>
      <span style={{ opacity: .5 }}>{scheme}://</span>
      <span>{"yourapp.com" + path + (showQuery ? "?ref=share" : "")}</span>
      <span aria-hidden="true" style={{ color: accent, fontFamily: "system-ui, sans-serif" }}>&#8594;</span>
    </a>
  );
}
